('01996533-c470-7186-8aff-58267983f830', '01995dec-678e-70cf-854a-b25e2c2d0d28', '01995e24-1a61-73eb-b623-a0220a69532e', 'int panjang = 20;\nint lebar = 20;\nint tinggi = 7;\nlong volume;\nSystem.out.println(\"Panjang: \" + panjang + \", Lebar: \" + lebar + \", Tinggi: \" + tinggi);\nvolume = panjang * lebar * tinggi;\nSystem.out.println(\"Volume setiap box nasi sebesar: \" + volume);', 'Panjang: 20, Lebar: 20, Tinggi: 7\r\nVolume setiap box nasi sebesar: 2800', '2025-09-20 03:38:35', '2025-09-22 07:16:45', NULL, 'medium'),
