('01996543-dbbf-73ec-b0d6-ff48905b627a', '01995e0c-9825-73b3-b94f-2ae0542eabef', '01995e2b-056e-716f-a01a-2794060829e0', 'import java.util.Scanner;\r\npublic class Main {\r\npublic static void main(String[] args) {\r\nScanner input = new Scanner(System.in);\r\nSystem.out.print(\"Masukkan usia Anda: \");\r\nint usia = input.nextInt();\r\nSystem.out.println(\"Usia Anda adalah \" + usia + \" tahun.\");\r\n}\r\n}', 'Masukkan usia Anda: Usia Anda adalah 22 tahun.', '2025-09-20 03:56:10', '2026-04-21 21:51:20', NULL, 'easy'),
('019966b3-d61f-733a-be06-733c496cdacc', '01995e0c-9825-73b3-b94f-2ae0542eabef', '0199656f-eb1f-70c7-b952-1825aa45f75c', 'float ipk;\nint toefl;\nint attitude;\nipk = 3.5;\ntoefl = 480;\nattitude = 75;\nif (ipk >= 3.5 && toefl >= 450) {\nif (attitude >= 60 && attitude <= 100) {\nSystem.out.print(\"Pelamar dinyatakan lolos seleksi administrasi\");\n} else {\nSystem.out.print(\"Pelamar dinyatakan tidak lolos seleksi administrasi\");\n}\n} else if (ipk >= 3.4 && toefl >= 400 && attitude >= 80 && attitude <= 100) {\nSystem.out.print(\"Pelamar dinyatakan lolos bersyarat seleksi administrasi\");\n} else {\nSystem.out.print(\"Pelamar dinyatakan tidak lolos seleksi administrasi\");\n}', 'Pelamar dinyatakan lolos seleksi administrasi', '2025-09-20 10:38:05', '2025-10-02 06:12:00', NULL, 'easy'),
('019966d2-47f3-70f0-9024-24da44ca3981', '01995e0c-9825-73b3-b94f-2ae0542eabef', '0199657d-34ff-739e-bfef-e842ea2e57d3', 'String member_card;\nint tot_belanja;\nfloat diskon;\nint bayar;\ntot_belanja = 300000;\nmember_card = \"ya\";\nif (member_card.equalsIgnoreCase(\"ya\")) {\nif (tot_belanja > 500000) {\nSystem.out.println(\"diskon 10%\");\n} else if (tot_belanja >= 251000 && tot_belanja <= 500000) {\nSystem.out.println(\"diskon 5%\");\n} else if (tot_belanja >= 150000 && tot_belanja <= 250000) {\nSystem.out.println(\"diskon 2%\");\n} else {\nSystem.out.println(\"diskon 0%\");\n}\n}', 'diskon 5%', '2025-09-20 11:11:21', '2025-10-02 05:56:42', NULL, 'medium'),
('019966e6-b2f8-724f-96d8-d179a6452519', '01995e0c-9825-73b3-b94f-2ae0542eabef', '01996581-d9fc-7116-ac8c-a860cd1b79bd', 'int age;\nage = 18;\nif (age >= 13 && age <= 16) {\nSystem.out.println(\"Anda hanya dapat menonton film dengan label Semua Umur (SU)\");\n} else if (age >= 17 && age <= 20) {\nSystem.out.println(\"Anda dapat menonton film dengan label Semua Umur (SU) dan 17+\");\n} else if (age >= 21) {\nSystem.out.println(\"Anda dapat menonton film dengan label semua jenis film\");\n} else {\nSystem.out.println(\"Anda tidak memenuhi kriteria untuk menonton film\");\n}', 'Anda dapat menonton film dengan label Semua Umur (SU) dan 17+', '2025-09-20 11:33:39', '2025-10-02 05:49:41', NULL, 'medium'),
