('01996701-587b-716d-8987-f42601e1a3e5', '01985f44-f662-72f9-a85b-a7b256942492', '019965b3-5dc1-733a-96f3-167263ed3ac1', 'double[] stackSetoran = new double[100];\ndouble setoran;\nint top;\nString jawaban;\nsetoran = 3500000;\ntop = -1;\nif (setoran > 3000000) {\nSystem.out.println(\"Ingin menambah setoran? (ya/tidak)\");\njawaban = \"ya\";\nif (jawaban.equalsIgnoreCase(\"ya\")) {\nstackSetoran[++top] = setoran;\n}\n}\nSystem.out.println(\"Jumlah setoran: \" + setoran);', 'Ingin menambah setoran? (ya/tidak)\r\nJumlah setoran: 3500000.0', '2025-09-20 12:02:45', '2025-10-03 12:14:33', NULL, 'easy'),
